 const grid=Array.from({length:5},(_,i)=>{const v=min+span*i/4;return line?`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${num(v,2)}</text>`:`<line x1="${x(v)}" x2="${x(v)}" y1="${top}" y2="${h-bottom}"/><text x="${x(v)}" y="${h-20}" text-anchor="middle">${num(v,2)}</text>`;}).join('');
 const pathFor=key=>{let pen=false;return rows.map((r,i)=>{if(r[key]==null){pen=false;return '';}if(r.gapBefore?.[key])pen=false;const part=`${pen?'L':'M'} ${px(i)} ${y(r[key])}`;pen=true;return part;}).join(' ');};
